// Host transport review, independent Gnark reverification, and descriptive analysis.
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::{Path,PathBuf}};use serde_json::{json,Value};use sha2::{Digest,Sha256};
const R:&str="/home/ubuntu/src/zopro-perf-work/ready-solver246";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn save(p:impl AsRef<Path>,v:Value){assert!(!p.as_ref().exists());fs::write(p,serde_json::to_vec_pretty(&v).unwrap()).unwrap();}
fn receipt(p:&Path){let e=read(p.join("exit.json"));assert_eq!(e["success"],true);assert_eq!(e["returncode"],0);for k in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{k}.log"))),e[format!("{k}_sha256")].as_str().unwrap());}}
fn near(x:f64,y:f64){assert!(x.is_finite()&&y.is_finite()&&(x-y).abs()<=x.abs().max(y.abs()).max(1.)*1e-10);}
fn ranks(v:&[f64])->Value{assert_eq!(v.len(),9);let mut a=v.to_vec();assert!(a.iter().all(|x|x.is_finite()&&*x>=0.));a.sort_by(f64::total_cmp);json!({"lower":a[1],"median":a[4],"upper":a[7],"all":v,"marginal_coverage":0.9609375,"familywise":false})}
fn main(){let r=Path::new(R);let mode=std::env::args().nth(1).unwrap();let root=r.join("bundle");let out=r.join("remote/output");let cfg=read(root.join("config/config.json"));let jobs=read(out.join("jobs.json"));let js=jobs.as_array().unwrap();assert_eq!(js.len(),90);let host=r.join("host-remote");
    let proofdir=|j:&Value|{let p=out.join("proofs").join(j["name"].as_str().unwrap());if j["engine"]=="aeglos"{p.join(j["case"]["id"].as_str().unwrap())}else{p}};
    if mode=="prepare"{assert_eq!(read(r.join("retrieved.json"))["verified_remote_digest"],true);assert_eq!(read(out.join("complete.json"))["status"],"complete");assert_eq!(read(out.join("independent-finish.json"))["passed"],true);fs::create_dir(&host).unwrap();let mut pins=BTreeMap::new();let verify=root.join("bin/verify");pins.insert(verify.display().to_string(),hash(&verify));let mut steps=vec![];
        for j in js{assert_eq!(j["case"],cfg["cases"][j["case"]["shape"].as_str().unwrap()]);let pd=proofdir(j);for f in["0.proof","0.public"]{let p=pd.join(f);pins.insert(p.display().to_string(),hash(&p));}let image=root.join(j["case"]["image"].as_str().unwrap());pins.insert(image.display().to_string(),j["case"]["image_sha256"].as_str().unwrap().into());steps.push(json!({"kind":"command","name":format!("verify-{}",j["name"].as_str().unwrap()),"argv":[verify.clone(),image,PathBuf::from(j["case"]["image_sha256"].as_str().unwrap()),pd.join("0.proof"),pd.join("0.public"),PathBuf::from(j["case"]["public_sha256"].as_str().unwrap())],"timeout_seconds":300}));}
        save(host.join("pins.json"),json!(pins));save(host.join("plan.json"),json!({"version":1,"source_pins":host.join("pins.json"),"steps":steps}));println!("Prepared90 host Gnark reverifications; no new proof count");return
    }
    assert_eq!(mode,"finish");assert_eq!(read(host.join("run/result.json"))["status"],"complete");
    let mut ledger:BTreeSet<String>=serde_json::from_value(read(root.join("config/seed.json"))).unwrap();assert_eq!(ledger.len(),64211);let mut seen=BTreeSet::new();let rows=read(out.join("rows.json"));assert_eq!(rows.as_array().unwrap().len(),90);let mut calls=0;let mut processes=vec![];let mut max_rss:BTreeMap<(String,u64,String),f64>=BTreeMap::new();
    for(i,j)in js.iter().enumerate(){let name=j["name"].as_str().unwrap();assert!(seen.insert(name));assert_eq!(j["case"],cfg["cases"][j["case"]["shape"].as_str().unwrap()]);let pre=j["preflight"]==true;let phase=j["phase"].as_str().unwrap();let n=if pre{1}else if phase=="profile"{251}else if j["case"]["shape"]=="1x2"{151}else if j["case"]["shape"]=="2x2"{51}else{17};assert_eq!(j["rounds"],n);calls+=n+3;let dir=out.join(format!("{phase}-run/{name}"));receipt(&dir);receipt(&out.join(format!("{}-verify-run/verify-{name}",if pre{"preflight"}else{"late"})));let raw=fs::read_to_string(dir.join("stdout.log")).unwrap();let samples=raw.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();let ss=raw.lines().filter_map(|l|l.strip_prefix("SUMMARY ")).map(|l|serde_json::from_str::<Value>(l).unwrap()).collect::<Vec<_>>();assert_eq!(ss.len(),1);let s=&ss[0];assert_eq!(samples.len(),n as usize);assert_eq!(s["priming"],3);assert_eq!(s["rounds"],n);let z=j["engine"]=="zopro";let mut total=0.;for(k,v)in samples.iter().enumerate(){assert_eq!(v["round"],k);let x=v[if z{"ms"}else{"verified_ms"}].as_f64().unwrap();assert!(x.is_finite()&&x>0.);total+=x;if !z{assert_eq!(v["cache_hit"],true);}}let mean=total/n as f64;let cpu=(s["user_cpu_ms"].as_f64().unwrap()+s["system_cpu_ms"].as_f64().unwrap())/n as f64;let rss=s["whole_process_maxrss_kib"].as_f64().unwrap()/1024.;assert!(rss>0.);let pd=proofdir(j);let ph=hash(pd.join("0.proof"));assert!(ledger.insert(ph.clone()));assert_eq!(fs::metadata(pd.join("0.proof")).unwrap().len(),164);assert_eq!(hash(pd.join("0.public")),j["case"]["public_sha256"].as_str().unwrap());let vd=host.join(format!("run/verify-{name}"));receipt(&vd);let verdict=fs::read_to_string(vd.join("stdout.log")).unwrap();assert!(verdict.contains(&format!("VERIFIED proof_sha256={ph} ")));assert!(verdict.contains(&format!(" image_sha256={}",j["case"]["image_sha256"].as_str().unwrap())));
        let row=&rows[i];assert_eq!(row["job"],*j);assert_eq!(row["summary"],*s);assert_eq!(row["proof_sha256"],ph);near(row["mean_ms"].as_f64().unwrap(),mean);near(row["cpu_ms"].as_f64().unwrap(),cpu);near(row["rss_mib"].as_f64().unwrap(),rss);
        let context=(j["case"]["shape"].as_str().unwrap().to_string(),j["workers"].as_u64().unwrap(),j["arm"].as_str().unwrap().to_string());max_rss.entry(context).and_modify(|x|*x=x.max(rss)).or_insert(rss);
        processes.push(json!({"name":name,"phase":j["phase"],"panel":j["panel"],"binary":j["binary"],"data":j["data"],"summary":s,"shape":j["case"]["shape"],"workers":j["workers"],"arm":j["arm"],"preflight":pre,"block":j["block"],"backing":j["backing"],"rounds":n,"round_times_ms":samples.iter().map(|v|v[if z{"ms"}else{"verified_ms"}].clone()).collect::<Vec<_>>(),"mean_ms":mean,"CPU_ms_per_request":cpu,"lifetime_RSS_MiB":rss,"loop_minor_faults":s["minor_faults"],"loop_major_faults":s["major_faults"],"voluntary_switches":s["voluntary_switches"],"involuntary_switches":s["involuntary_switches"],"public_sha256":j["case"]["public_sha256"],"image_sha256":j["case"]["image_sha256"],"aeglos_key_sha256":j["case"]["aeglos_key_sha256"]}));
    }
    assert_eq!(calls,8748);let saved:BTreeSet<String>=serde_json::from_value(read(out.join("proof-sha256.json"))).unwrap();assert_eq!(saved,ledger);assert_eq!(ledger.len(),64301);assert_eq!(read(out.join("complete.json"))["canonical_sha256"],hash(out.join("proof-sha256.json")));
    assert_eq!(processes.len(),90);save(r.join("host-rows.json"),json!(processes));
    for(p,h)in read(r.join("production-manifest.json"))["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}
    save(host.join("proof-sha256.json"),json!(ledger));save(host.join("review.json"),json!({"passed":true,"host_reverified_exports":90,"new_remote_exports":90,"new_local_exports":0,"sdk_calls_remote":8748,"canonical_count":64301,"canonical_sha256":hash(host.join("proof-sha256.json")),"production_188_unchanged":true}));println!("Host90 fresh exports PASS; canonical64301; diagnostic-only profiles awaitqualityanalysis");
}
